  ('prohibited-distributor', 15, 'distributor', 'prohibited', null, 'This system can''t lawfully be placed on the EU market or used (Art. 5). The Act doesn''t name distributors in Art. 5, but don''t supply it.', 'art:5:1', '2025-02-02', 'The practice falls under Art. 5(1) points (a) to (h).', true, null, null, 'amended', 'Don''t supply it: it can''t lawfully be sold or used in the EU', 'Nicht liefern: Es darf in der EU weder in Verkehr gebracht noch verwendet werden', 'Dieses System darf in der EU nicht rechtmäßig in Verkehr gebracht oder verwendet werden (Art. 5). Art. 5 nennt Händler nicht ausdrücklich, liefern Sie es dennoch nicht.', null, null),
  ('prohibited-distributor-intimate-imagery', 16, 'distributor', 'prohibited', null, 'This system can''t lawfully be placed on the EU market or used (Art. 5). The Act doesn''t name distributors in Art. 5, but don''t supply it.', 'art:5:1:ba', '2026-12-02', 'The system generates or manipulates realistic intimate or sexually explicit images, video or audio of an identifiable person without their explicit consent.', true, null, null, 'amended', 'Don''t supply it: it can''t lawfully be sold or used in the EU', 'Nicht liefern: Es darf in der EU weder in Verkehr gebracht noch verwendet werden', 'Dieses System darf in der EU nicht rechtmäßig in Verkehr gebracht oder verwendet werden (Art. 5). Art. 5 nennt Händler nicht ausdrücklich, liefern Sie es dennoch nicht.', null, null),
  ('prohibited-distributor-csam', 17, 'distributor', 'prohibited', null, 'This system can''t lawfully be placed on the EU market or used (Art. 5). The Act doesn''t name distributors in Art. 5, but don''t supply it.', 'art:5:1:bb', '2026-12-02', 'The system generates or manipulates child sexual abuse material.', true, null, null, 'amended', 'Don''t supply it: it can''t lawfully be sold or used in the EU', 'Nicht liefern: Es darf in der EU weder in Verkehr gebracht noch verwendet werden', 'Dieses System darf in der EU nicht rechtmäßig in Verkehr gebracht oder verwendet werden (Art. 5). Art. 5 nennt Händler nicht ausdrücklich, liefern Sie es dennoch nicht.', null, null),
  ('hr-provider-requirements', 18, 'provider', 'high_risk', 'annex_i', 'Make sure the system meets the high-risk requirements: risk management, data governance, technical documentation, logging, instructions for deployers, human oversight, accuracy, robustness and cybersecurity (Art. 9 to 15).', 'art:16:a', '2028-08-02', null, false, null, null, 'amended', 'Build it to meet the high-risk requirements, from risk management to cybersecurity', 'Die Hochrisiko-Anforderungen erfüllen, vom Risikomanagement bis zur Cybersicherheit', 'Sicherstellen, dass das System die Anforderungen an Hochrisiko-KI-Systeme erfüllt: Risikomanagementsystem, Daten und Daten-Governance, technische Dokumentation, Aufzeichnungspflichten, Transparenz und Bereitstellung von Informationen für die Betreiber, menschliche Aufsicht sowie Genauigkeit, Robustheit und Cybersicherheit (Art. 9 bis 15).', 'build', 'art_9_risk_management'),
  ('hr-provider-requirements', 19, 'provider', 'high_risk', 'annex_iii', 'Make sure the system meets the high-risk requirements: risk management, data governance, technical documentation, logging, instructions for deployers, human oversight, accuracy, robustness and cybersecurity (Art. 9 to 15).', 'art:16:a', '2027-12-02', null, false, null, null, 'amended', 'Build it to meet the high-risk requirements, from risk management to cybersecurity', 'Die Hochrisiko-Anforderungen erfüllen, vom Risikomanagement bis zur Cybersicherheit', 'Sicherstellen, dass das System die Anforderungen an Hochrisiko-KI-Systeme erfüllt: Risikomanagementsystem, Daten und Daten-Governance, technische Dokumentation, Aufzeichnungspflichten, Transparenz und Bereitstellung von Informationen für die Betreiber, menschliche Aufsicht sowie Genauigkeit, Robustheit und Cybersicherheit (Art. 9 bis 15).', 'build', 'art_9_risk_management'),
  ('hr-provider-contact', 20, 'provider', 'high_risk', 'annex_i', 'Put your name, registered trade name or trade mark and contact address on the system, its packaging or its documentation.', 'art:16:b', '2028-08-02', null, false, null, null, 'amended', 'Put your name and contact address on it', 'Ihren Namen und Ihre Kontaktanschrift darauf angeben', 'Ihren Namen, Ihren eingetragenen Handelsnamen bzw. Ihre eingetragene Handelsmarke und Ihre Kontaktanschrift auf dem System oder, falls dies nicht möglich ist, auf seiner Verpackung oder in der beigefügten Dokumentation angeben.', 'prove', null),
  ('hr-provider-contact', 21, 'provider', 'high_risk', 'annex_iii', 'Put your name, registered trade name or trade mark and contact address on the system, its packaging or its documentation.', 'art:16:b', '2027-12-02', null, false, null, null, 'amended', 'Put your name and contact address on it', 'Ihren Namen und Ihre Kontaktanschrift darauf angeben', 'Ihren Namen, Ihren eingetragenen Handelsnamen bzw. Ihre eingetragene Handelsmarke und Ihre Kontaktanschrift auf dem System oder, falls dies nicht möglich ist, auf seiner Verpackung oder in der beigefügten Dokumentation angeben.', 'prove', null),
  ('hr-provider-qms', 22, 'provider', 'high_risk', 'annex_i', 'Have a documented quality management system (Art. 17).', 'art:16:c', '2028-08-02', null, false, 'The quality management system may be proportionate to the size of the organisation for SMEs, including start-ups, and SMCs (Art. 17(2)). SMEs without partner or linked enterprises may comply with certain elements in a simplified manner (Art. 63(1)).', null, 'amended', 'Set up a quality management system', 'Ein Qualitätsmanagementsystem einrichten', 'Über ein dokumentiertes Qualitätsmanagementsystem verfügen, das Art. 17 entspricht.', 'prove', 'art_17_quality_management'),
  ('hr-provider-qms', 23, 'provider', 'high_risk', 'annex_iii', 'Have a documented quality management system (Art. 17).', 'art:16:c', '2027-12-02', null, false, 'The quality management system may be proportionate to the size of the organisation for SMEs, including start-ups, and SMCs (Art. 17(2)). SMEs without partner or linked enterprises may comply with certain elements in a simplified manner (Art. 63(1)).', null, 'amended', 'Set up a quality management system', 'Ein Qualitätsmanagementsystem einrichten', 'Über ein dokumentiertes Qualitätsmanagementsystem verfügen, das Art. 17 entspricht.', 'prove', 'art_17_quality_management'),
  ('hr-provider-technical-documentation', 24, 'provider', 'high_risk', 'annex_i', 'Draw up the technical documentation (Annex IV) before placing the system on the market, and keep it up to date.', 'art:11:1', '2028-08-02', null, false, 'SMEs, including start-ups, and SMCs may provide the Annex IV elements in a simplified manner, using the Commission''s simplified form (Art. 11(1)). As of 24 September 2026 the form did not appear to be published.', null, 'amended', 'Write the technical documentation and keep it up to date', 'Die technische Dokumentation erstellen und aktuell halten', 'Die technische Dokumentation (Anhang IV) erstellen, bevor das System in Verkehr gebracht oder in Betrieb genommen wird, und sie auf dem neuesten Stand halten.', 'prove', 'annex_iv_technical_documentation'),
  ('hr-provider-technical-documentation', 25, 'provider', 'high_risk', 'annex_iii', 'Draw up the technical documentation (Annex IV) before placing the system on the market, and keep it up to date.', 'art:11:1', '2027-12-02', null, false, 'SMEs, including start-ups, and SMCs may provide the Annex IV elements in a simplified manner, using the Commission''s simplified form (Art. 11(1)). As of 24 September 2026 the form did not appear to be published.', null, 'amended', 'Write the technical documentation and keep it up to date', 'Die technische Dokumentation erstellen und aktuell halten', 'Die technische Dokumentation (Anhang IV) erstellen, bevor das System in Verkehr gebracht oder in Betrieb genommen wird, und sie auf dem neuesten Stand halten.', 'prove', 'annex_iv_technical_documentation'),
  ('hr-provider-keep-documentation', 26, 'provider', 'high_risk', 'annex_i', 'Keep the technical documentation, quality management documents and declaration of conformity for 10 years (Art. 18).', 'art:16:d', '2028-08-02', null, false, null, null, 'amended', 'Keep the documentation and declaration for 10 years', 'Dokumentation und Konformitätserklärung zehn Jahre aufbewahren', 'Die technische Dokumentation, die Unterlagen zum Qualitätsmanagementsystem und die EU- Konformitätserklärung zehn Jahre lang aufbewahren (Art. 18).', 'after_launch', null),
  ('hr-provider-keep-documentation', 27, 'provider', 'high_risk', 'annex_iii', 'Keep the technical documentation, quality management documents and declaration of conformity for 10 years (Art. 18).', 'art:16:d', '2027-12-02', null, false, null, null, 'amended', 'Keep the documentation and declaration for 10 years', 'Dokumentation und Konformitätserklärung zehn Jahre aufbewahren', 'Die technische Dokumentation, die Unterlagen zum Qualitätsmanagementsystem und die EU- Konformitätserklärung zehn Jahre lang aufbewahren (Art. 18).', 'after_launch', null),
  ('hr-provider-logs', 28, 'provider', 'high_risk', 'annex_i', 'Keep the logs the system generates automatically, where they are under your control (Art. 19).', 'art:16:e', '2028-08-02', null, false, null, null, 'amended', 'Keep the logs it creates, where you control them', 'Die automatisch erzeugten Protokolle aufbewahren, soweit Sie sie kontrollieren', 'Die vom System automatisch erzeugten Protokolle gemäß Art. 19 aufbewahren, soweit sie Ihrer Kontrolle unterliegen.', 'after_launch', null),
  ('hr-provider-logs', 29, 'provider', 'high_risk', 'annex_iii', 'Keep the logs the system generates automatically, where they are under your control (Art. 19).', 'art:16:e', '2027-12-02', null, false, null, null, 'amended', 'Keep the logs it creates, where you control them', 'Die automatisch erzeugten Protokolle aufbewahren, soweit Sie sie kontrollieren', 'Die vom System automatisch erzeugten Protokolle gemäß Art. 19 aufbewahren, soweit sie Ihrer Kontrolle unterliegen.', 'after_launch', null),
  ('hr-provider-conformity-assessment', 30, 'provider', 'high_risk', 'annex_i', 'Have the system undergo the relevant conformity assessment (Art. 43) before placing it on the market or putting it into service.', 'art:16:f', '2028-08-02', null, false, null, null, 'amended', 'Have its conformity assessed before launch', 'Vor dem Marktstart die Konformitätsbewertung durchlaufen', 'Sicherstellen, dass das System vor dem Inverkehrbringen oder der Inbetriebnahme dem betreffenden Konformitätsbewertungsverfahren gemäß Art. 43 unterzogen wird.', 'prove', null),
  ('hr-provider-conformity-assessment', 31, 'provider', 'high_risk', 'annex_iii', 'Have the system undergo the relevant conformity assessment (Art. 43) before placing it on the market or putting it into service.', 'art:16:f', '2027-12-02', null, false, null, null, 'amended', 'Have its conformity assessed before launch', 'Vor dem Marktstart die Konformitätsbewertung durchlaufen', 'Sicherstellen, dass das System vor dem Inverkehrbringen oder der Inbetriebnahme dem betreffenden Konformitätsbewertungsverfahren gemäß Art. 43 unterzogen wird.', 'prove', null),
  ('hr-provider-declaration', 32, 'provider', 'high_risk', 'annex_i', 'Draw up an EU declaration of conformity (Art. 47).', 'art:16:g', '2028-08-02', null, false, null, null, 'amended', 'Sign the EU declaration of conformity', 'Die EU-Konformitätserklärung ausstellen', 'Eine EU-Konformitätserklärung gemäß Art. 47 ausstellen.', 'prove', null),
  ('hr-provider-declaration', 33, 'provider', 'high_risk', 'annex_iii', 'Draw up an EU declaration of conformity (Art. 47).', 'art:16:g', '2027-12-02', null, false, null, null, 'amended', 'Sign the EU declaration of conformity', 'Die EU-Konformitätserklärung ausstellen', 'Eine EU-Konformitätserklärung gemäß Art. 47 ausstellen.', 'prove', null),
  ('hr-provider-ce-marking', 34, 'provider', 'high_risk', 'annex_i', 'Affix the CE marking to the system, its packaging or its documentation (Art. 48).', 'art:16:h', '2028-08-02', null, false, null, null, 'amended', 'Affix the CE marking', 'Die CE-Kennzeichnung anbringen', 'Die CE-Kennzeichnung gemäß Art. 48 am System oder, falls dies nicht möglich ist, auf seiner Verpackung oder in der beigefügten Dokumentation anbringen.', 'prove', null),
  ('hr-provider-ce-marking', 35, 'provider', 'high_risk', 'annex_iii', 'Affix the CE marking to the system, its packaging or its documentation (Art. 48).', 'art:16:h', '2027-12-02', null, false, null, null, 'amended', 'Affix the CE marking', 'Die CE-Kennzeichnung anbringen', 'Die CE-Kennzeichnung gemäß Art. 48 am System oder, falls dies nicht möglich ist, auf seiner Verpackung oder in der beigefügten Dokumentation anbringen.', 'prove', null),
  ('hr-provider-registration', 36, 'provider', 'high_risk', 'annex_iii', 'Register yourself and the system in the EU database before placing it on the market (Art. 49(1)).', 'art:16:i', '2027-12-02', null, false, null, 'Systems in Annex III point 2 (critical infrastructure) are registered at national level instead (Art. 49(5)).', 'amended', 'Register it in the EU database', 'Es in der EU-Datenbank registrieren', 'Sich und das System vor dem Inverkehrbringen oder der Inbetriebnahme in der EU-Datenbank registrieren (Art. 49 Abs. 1).', 'prove', null),
  ('hr-provider-corrective-actions', 37, 'provider', 'high_risk', 'annex_i', 'Take corrective action and inform others when the system is not in conformity (Art. 20).', 'art:16:j', '2028-08-02', null, false, null, null, 'amended', 'Take corrective action and inform others if it doesn''t conform', 'Korrekturmaßnahmen ergreifen und andere informieren, wenn es nicht konform ist', 'Die erforderlichen Korrekturmaßnahmen ergreifen und die gemäß Art. 20 erforderlichen Informationen bereitstellen, wenn das System nicht konform ist.', 'after_launch', null),
  ('hr-provider-corrective-actions', 38, 'provider', 'high_risk', 'annex_iii', 'Take corrective action and inform others when the system is not in conformity (Art. 20).', 'art:16:j', '2027-12-02', null, false, null, null, 'amended', 'Take corrective action and inform others if it doesn''t conform', 'Korrekturmaßnahmen ergreifen und andere informieren, wenn es nicht konform ist', 'Die erforderlichen Korrekturmaßnahmen ergreifen und die gemäß Art. 20 erforderlichen Informationen bereitstellen, wenn das System nicht konform ist.', 'after_launch', null),
  ('hr-provider-demonstrate-conformity', 39, 'provider', 'high_risk', 'annex_i', 'Demonstrate the system''s conformity when a national competent authority asks.', 'art:16:k', '2028-08-02', null, false, null, null, 'amended', 'Show an authority it conforms, when asked', 'Auf Anfrage einer Behörde die Konformität nachweisen', 'Auf begründete Anfrage einer zuständigen nationalen Behörde nachweisen, dass das System die Anforderungen an Hochrisiko-KI-Systeme erfüllt.', 'prove', null),
  ('hr-provider-demonstrate-conformity', 40, 'provider', 'high_risk', 'annex_iii', 'Demonstrate the system''s conformity when a national competent authority asks.', 'art:16:k', '2027-12-02', null, false, null, null, 'amended', 'Show an authority it conforms, when asked', 'Auf Anfrage einer Behörde die Konformität nachweisen', 'Auf begründete Anfrage einer zuständigen nationalen Behörde nachweisen, dass das System die Anforderungen an Hochrisiko-KI-Systeme erfüllt.', 'prove', null),
  ('hr-provider-accessibility', 41, 'provider', 'high_risk', 'annex_i', 'Make sure the system meets the accessibility requirements of Directives (EU) 2016/2102 and (EU) 2019/882.', 'art:16:l', '2028-08-02', null, false, null, null, 'amended', 'Make it accessible to people with disabilities', 'Es barrierefrei gestalten', 'Sicherstellen, dass das System die Barrierefreiheitsanforderungen gemäß den Richtlinien (EU) 2016/2102 und (EU) 2019/882 erfüllt.', 'build', null),
  ('hr-provider-accessibility', 42, 'provider', 'high_risk', 'annex_iii', 'Make sure the system meets the accessibility requirements of Directives (EU) 2016/2102 and (EU) 2019/882.', 'art:16:l', '2027-12-02', null, false, null, null, 'amended', 'Make it accessible to people with disabilities', 'Es barrierefrei gestalten', 'Sicherstellen, dass das System die Barrierefreiheitsanforderungen gemäß den Richtlinien (EU) 2016/2102 und (EU) 2019/882 erfüllt.', 'build', null),
  ('hr-provider-authorised-representative', 43, 'provider', 'high_risk', 'annex_i', 'Appoint an authorised representative established in the Union, by written mandate, before making the system available.', 'art:22:1', '2028-08-02', 'The provider is established outside the Union.', false, null, null, 'amended', 'Appoint an authorised representative in the EU', 'Einen Bevollmächtigten in der EU benennen', 'Vor der Bereitstellung des Systems auf dem Unionsmarkt schriftlich einen in der Union niedergelassenen Bevollmächtigten benennen.', 'prove', null),
  ('hr-provider-authorised-representative', 44, 'provider', 'high_risk', 'annex_iii', 'Appoint an authorised representative established in the Union, by written mandate, before making the system available.', 'art:22:1', '2027-12-02', 'The provider is established outside the Union.', false, null, null, 'amended', 'Appoint an authorised representative in the EU', 'Einen Bevollmächtigten in der EU benennen', 'Vor der Bereitstellung des Systems auf dem Unionsmarkt schriftlich einen in der Union niedergelassenen Bevollmächtigten benennen.', 'prove', null),
  ('hr-provider-post-market-monitoring', 45, 'provider', 'high_risk', 'annex_i', 'Set up and document a post-market monitoring system based on a monitoring plan.', 'art:72:1', '2028-08-02', null, false, null, 'Chapter IX formally applies from 2 August 2026 (Art. 113, general date), but these duties only reach high-risk systems once their high-risk rules apply.', 'amended', 'Monitor how it performs in use', 'Beobachten, wie es sich im Einsatz bewährt', 'Ein System zur Beobachtung nach dem Inverkehrbringen auf Grundlage eines Plans für die Beobachtung nach dem Inverkehrbringen einrichten und dokumentieren.', 'after_launch', null),
  ('hr-provider-post-market-monitoring', 46, 'provider', 'high_risk', 'annex_iii', 'Set up and document a post-market monitoring system based on a monitoring plan.', 'art:72:1', '2027-12-02', null, false, null, 'Chapter IX formally applies from 2 August 2026 (Art. 113, general date), but these duties only reach high-risk systems once their high-risk rules apply.', 'amended', 'Monitor how it performs in use', 'Beobachten, wie es sich im Einsatz bewährt', 'Ein System zur Beobachtung nach dem Inverkehrbringen auf Grundlage eines Plans für die Beobachtung nach dem Inverkehrbringen einrichten und dokumentieren.', 'after_launch', null),
  ('hr-provider-serious-incidents', 47, 'provider', 'high_risk', 'annex_i', 'Report serious incidents to the market surveillance authority: at the latest 15 days after becoming aware, 10 days in case of death, 2 days for a widespread infringement.', 'art:73:1', '2028-08-02', null, false, null, 'Chapter IX formally applies from 2 August 2026 (Art. 113, general date), but these duties only reach high-risk systems once their high-risk rules apply.', 'amended', 'Report serious incidents to the authority', 'Schwerwiegende Vorfälle der Behörde melden', 'Schwerwiegende Vorfälle der Marktüberwachungsbehörde melden: spätestens 15 Tage, nachdem Sie davon Kenntnis erlangt haben, im Todesfall spätestens nach zehn Tagen, bei einem weitverbreiteten Verstoß spätestens nach zwei Tagen.', 'after_launch', null),
  ('hr-provider-serious-incidents', 48, 'provider', 'high_risk', 'annex_iii', 'Report serious incidents to the market surveillance authority: at the latest 15 days after becoming aware, 10 days in case of death, 2 days for a widespread infringement.', 'art:73:1', '2027-12-02', null, false, null, 'Chapter IX formally applies from 2 August 2026 (Art. 113, general date), but these duties only reach high-risk systems once their high-risk rules apply.', 'amended', 'Report serious incidents to the authority', 'Schwerwiegende Vorfälle der Behörde melden', 'Schwerwiegende Vorfälle der Marktüberwachungsbehörde melden: spätestens 15 Tage, nachdem Sie davon Kenntnis erlangt haben, im Todesfall spätestens nach zehn Tagen, bei einem weitverbreiteten Verstoß spätestens nach zwei Tagen.', 'after_launch', null),
  ('hr-deployer-instructions', 49, 'deployer', 'high_risk', 'annex_i', 'Use the system according to the provider''s instructions for use, with appropriate technical and organisational measures.', 'art:26:1', '2028-08-02', null, false, null, null, 'amended', 'Use the tool as the vendor''s instructions say', 'Das Tool gemäß der Betriebsanleitung des Anbieters einsetzen', 'Das System gemäß der beigefügten Betriebsanleitung verwenden und dafür geeignete technische und organisatorische Maßnahmen treffen.', null, null),
  ('hr-deployer-instructions', 50, 'deployer', 'high_risk', 'annex_iii', 'Use the system according to the provider''s instructions for use, with appropriate technical and organisational measures.', 'art:26:1', '2027-12-02', null, false, null, null, 'amended', 'Use the tool as the vendor''s instructions say', 'Das Tool gemäß der Betriebsanleitung des Anbieters einsetzen', 'Das System gemäß der beigefügten Betriebsanleitung verwenden und dafür geeignete technische und organisatorische Maßnahmen treffen.', null, null),
  ('hr-deployer-human-oversight', 51, 'deployer', 'high_risk', 'annex_i', 'Assign human oversight to people with the necessary competence, training, authority and support.', 'art:26:2', '2028-08-02', null, false, null, null, 'amended', 'Put trained people in charge of reviewing its output', 'Geschulten Personen die menschliche Aufsicht übertragen', 'Die menschliche Aufsicht natürlichen Personen übertragen, die über die erforderliche Kompetenz, Ausbildung und Befugnis verfügen, und ihnen die erforderliche Unterstützung zukommen lassen.', null, 'art_26_2_oversight'),
  ('hr-deployer-human-oversight', 52, 'deployer', 'high_risk', 'annex_iii', 'Assign human oversight to people with the necessary competence, training, authority and support.', 'art:26:2', '2027-12-02', null, false, null, null, 'amended', 'Put trained people in charge of reviewing its output', 'Geschulten Personen die menschliche Aufsicht übertragen', 'Die menschliche Aufsicht natürlichen Personen übertragen, die über die erforderliche Kompetenz, Ausbildung und Befugnis verfügen, und ihnen die erforderliche Unterstützung zukommen lassen.', null, 'art_26_2_oversight'),
  ('hr-deployer-input-data', 53, 'deployer', 'high_risk', 'annex_i', 'Make sure the input data is relevant and sufficiently representative for the intended purpose.', 'art:26:4', '2028-08-02', 'You control the input data.', false, null, null, 'amended', 'Check that the input data suits the purpose, where you control it', 'Prüfen, ob die Eingabedaten zum Zweck passen, soweit Sie sie kontrollieren', 'Dafür sorgen, dass die Eingabedaten der Zweckbestimmung des Systems entsprechen und ausreichend repräsentativ sind.', null, null),
  ('hr-deployer-input-data', 54, 'deployer', 'high_risk', 'annex_iii', 'Make sure the input data is relevant and sufficiently representative for the intended purpose.', 'art:26:4', '2027-12-02', 'You control the input data.', false, null, null, 'amended', 'Check that the input data suits the purpose, where you control it', 'Prüfen, ob die Eingabedaten zum Zweck passen, soweit Sie sie kontrollieren', 'Dafür sorgen, dass die Eingabedaten der Zweckbestimmung des Systems entsprechen und ausreichend repräsentativ sind.', null, null),
  ('hr-deployer-monitoring', 55, 'deployer', 'high_risk', 'annex_i', 'Monitor the system''s operation; if it presents a risk, inform the provider or distributor and the market surveillance authority and suspend its use; report serious incidents to the provider first.', 'art:26:5', '2028-08-02', null, false, null, null, 'amended', 'Watch how it performs and report serious problems to the vendor', 'Den Betrieb überwachen und schwerwiegende Probleme dem Anbieter melden', 'Den Betrieb des Systems überwachen; birgt es ein Risiko, den Anbieter oder Händler und die Marktüberwachungsbehörde informieren und die Verwendung aussetzen; schwerwiegende Vorfälle zuerst dem Anbieter melden.', null, null),
  ('hr-deployer-monitoring', 56, 'deployer', 'high_risk', 'annex_iii', 'Monitor the system''s operation; if it presents a risk, inform the provider or distributor and the market surveillance authority and suspend its use; report serious incidents to the provider first.', 'art:26:5', '2027-12-02', null, false, null, null, 'amended', 'Watch how it performs and report serious problems to the vendor', 'Den Betrieb überwachen und schwerwiegende Probleme dem Anbieter melden', 'Den Betrieb des Systems überwachen; birgt es ein Risiko, den Anbieter oder Händler und die Marktüberwachungsbehörde informieren und die Verwendung aussetzen; schwerwiegende Vorfälle zuerst dem Anbieter melden.', null, null),
  ('hr-deployer-logs', 57, 'deployer', 'high_risk', 'annex_i', 'Keep the logs the system generates, where they are under your control, for at least six months.', 'art:26:6', '2028-08-02', null, false, null, null, 'amended', 'Keep the logs it creates for at least six months', 'Die automatisch erzeugten Protokolle mindestens sechs Monate aufbewahren', 'Die vom System automatisch erzeugten Protokolle, soweit sie Ihrer Kontrolle unterliegen, mindestens sechs Monate aufbewahren.', null, null),
  ('hr-deployer-logs', 58, 'deployer', 'high_risk', 'annex_iii', 'Keep the logs the system generates, where they are under your control, for at least six months.', 'art:26:6', '2027-12-02', null, false, null, null, 'amended', 'Keep the logs it creates for at least six months', 'Die automatisch erzeugten Protokolle mindestens sechs Monate aufbewahren', 'Die vom System automatisch erzeugten Protokolle, soweit sie Ihrer Kontrolle unterliegen, mindestens sechs Monate aufbewahren.', null, null),
  ('hr-deployer-inform-workers', 59, 'deployer', 'high_risk', 'annex_i', 'Inform workers'' representatives and the affected workers before using the system at the workplace.', 'art:26:7', '2028-08-02', 'You are an employer and use the system at the workplace.', false, null, null, 'amended', 'Tell workers'' representatives and staff before you start', 'Arbeitnehmervertretung und Beschäftigte vor dem Einsatz informieren', 'Vor der Inbetriebnahme oder Verwendung am Arbeitsplatz die Arbeitnehmervertreter und die betroffenen Arbeitnehmer informieren, dass sie der Verwendung des Systems unterliegen werden.', null, 'art_26_7_workers'),
  ('hr-deployer-inform-workers', 60, 'deployer', 'high_risk', 'annex_iii', 'Inform workers'' representatives and the affected workers before using the system at the workplace.', 'art:26:7', '2027-12-02', 'You are an employer and use the system at the workplace.', false, null, null, 'amended', 'Tell workers'' representatives and staff before you start', 'Arbeitnehmervertretung und Beschäftigte vor dem Einsatz informieren', 'Vor der Inbetriebnahme oder Verwendung am Arbeitsplatz die Arbeitnehmervertreter und die betroffenen Arbeitnehmer informieren, dass sie der Verwendung des Systems unterliegen werden.', null, 'art_26_7_workers'),
  ('hr-deployer-registration', 61, 'deployer', 'high_risk', 'annex_iii', 'Register the use of the system in the EU database (Art. 49(3)); do not use a system that is not registered.', 'art:26:8', '2027-12-02', 'You are a public authority or a Union institution, body, office or agency.', false, null, null, 'amended', 'Register your use in the EU database, and don''t use an unregistered system', 'Die Verwendung in der EU-Datenbank registrieren und kein unregistriertes System einsetzen', 'Die Verwendung des Systems in der EU-Datenbank registrieren (Art. 49 Abs. 3); ein System, das dort nicht registriert ist, nicht verwenden.', null, null),
  ('hr-deployer-dpia', 62, 'deployer', 'high_risk', 'annex_i', 'Use the provider''s information (Art. 13) for your data protection impact assessment.', 'art:26:9', '2028-08-02', 'A data protection impact assessment is required under Art. 35 GDPR or Art. 27 of Directive (EU) 2016/680.', false, null, null, 'amended', 'Use the vendor''s information for your data protection impact assessment', 'Die Angaben des Anbieters für Ihre Datenschutz-Folgenabschätzung nutzen', 'Die gemäß Art. 13 bereitgestellten Informationen für Ihre Datenschutz-Folgenabschätzung verwenden.', null, null),
  ('hr-deployer-dpia', 63, 'deployer', 'high_risk', 'annex_iii', 'Use the provider''s information (Art. 13) for your data protection impact assessment.', 'art:26:9', '2027-12-02', 'A data protection impact assessment is required under Art. 35 GDPR or Art. 27 of Directive (EU) 2016/680.', false, null, null, 'amended', 'Use the vendor''s information for your data protection impact assessment', 'Die Angaben des Anbieters für Ihre Datenschutz-Folgenabschätzung nutzen', 'Die gemäß Art. 13 bereitgestellten Informationen für Ihre Datenschutz-Folgenabschätzung verwenden.', null, null),
  ('hr-deployer-post-remote-biometric', 64, 'deployer', 'high_risk', 'annex_iii', 'Get prior (or, at the latest within 48 hours, subsequent) authorisation from a judicial or binding administrative authority for each use, limit each use to a specific offence, document every use in the police file and report annually to the authorities.', 'art:26:10', '2027-12-02', 'You use post-remote biometric identification for law enforcement (targeted search of a person suspected or convicted of a criminal offence).', false, null, null, 'amended', 'Get authorisation for each use and limit it to a specific offence', 'Jede Verwendung genehmigen lassen und auf eine bestimmte Straftat beschränken', 'Für jede Verwendung vorab oder spätestens binnen 48 Stunden die Genehmigung einer Justizbehörde oder einer Verwaltungsbehörde mit bindender Entscheidung einholen, jede Verwendung auf die Ermittlung einer bestimmten Straftat beschränken, jede Verwendung in der Polizeiakte dokumentieren und den Behörden jährlich Bericht erstatten.', null, null),
  ('hr-deployer-inform-persons', 65, 'deployer', 'high_risk', 'annex_iii', 'Inform the people concerned that they are subject to the use of the high-risk system.', 'art:26:11', '2027-12-02', 'The system makes, or helps make, decisions about natural persons.', false, null, null, 'amended', 'Tell the people affected that it''s used in decisions about them', 'Betroffene Personen informieren, dass das Tool bei Entscheidungen über sie eingesetzt wird', 'Die betroffenen natürlichen Personen darüber informieren, dass sie der Verwendung des Hochrisiko-KI-Systems unterliegen.', null, 'art_26_11_affected'),
  ('hr-deployer-cooperate', 66, 'deployer', 'high_risk', 'annex_i', 'Cooperate with the competent authorities in any action they take about the system.', 'art:26:12', '2028-08-02', null, false, null, null, 'amended', 'Cooperate with the authorities when they act on it', 'Mit den Behörden bei ihren Maßnahmen zusammenarbeiten', 'Mit den zuständigen Behörden bei allen Maßnahmen zusammenarbeiten, die diese im Zusammenhang mit dem System ergreifen.', null, null),
  ('hr-deployer-cooperate', 67, 'deployer', 'high_risk', 'annex_iii', 'Cooperate with the competent authorities in any action they take about the system.', 'art:26:12', '2027-12-02', null, false, null, null, 'amended', 'Cooperate with the authorities when they act on it', 'Mit den Behörden bei ihren Maßnahmen zusammenarbeiten', 'Mit den zuständigen Behörden bei allen Maßnahmen zusammenarbeiten, die diese im Zusammenhang mit dem System ergreifen.', null, null),
  ('hr-deployer-fria', 68, 'deployer', 'high_risk', 'annex_iii', 'Carry out a fundamental rights impact assessment before first use, and notify the market surveillance authority of the results.', 'art:27:1', '2027-12-02', 'You are a body governed by public law or a private entity providing public services (except for Annex III point 2), or the system is used for creditworthiness or credit scoring, or for risk assessment and pricing in life and health insurance (Annex III points 5(b) and (c)).', false, null, 'The AI Office is to publish a questionnaire template to simplify this assessment (Art. 27(5)).', 'amended', 'Assess its impact on fundamental rights before first use', 'Vor der ersten Verwendung die Folgen für die Grundrechte abschätzen', 'Vor der ersten Verwendung eine Grundrechte-Folgenabschätzung durchführen und der Marktüberwachungsbehörde die Ergebnisse mitteilen.', null, 'art_27_fria'),
  ('hr-deployer-explanation', 69, 'deployer', 'high_risk', 'annex_iii', 'On request, give an affected person clear and meaningful explanations of the role of the system in the decision and the main elements of the decision taken.', 'art:86:1', '2027-12-02', 'Decisions taken on the basis of the system''s output produce legal effects on people or similarly significantly affect them (not for Annex III point 2, critical infrastructure).', false, null, 'Chapter IX formally applies from 2 August 2026 (Art. 113, general date), but these duties only reach high-risk systems once their high-risk rules apply.', 'amended', 'Explain its role in a decision when an affected person asks', 'Auf Anfrage Betroffener die Rolle des Systems bei einer Entscheidung erläutern', 'Betroffenen Personen auf Anfrage eine klare und aussagekräftige Erläuterung zur Rolle des Systems im Entscheidungsprozess und zu den wichtigsten Elementen der getroffenen Entscheidung geben.', null, null),
  ('hr-registration-non-public', 70, 'provider', 'high_risk', 'annex_iii', 'Register in the secure non-public section of the EU database, with only the reduced set of information Art. 49(4) lists; only the Commission and the authorities in Art. 74(8) can see it.', 'art:49:4', '2027-12-02', 'The system is listed in Annex III point 1, 6 or 7 and is used in law enforcement, migration, asylum or border control management.', false, null, 'Replaces the public registration of Art. 49(1) to (3) for these systems.', 'amended', 'Register it in the non-public section of the EU database', 'Es im nicht öffentlichen Teil der EU-Datenbank registrieren', 'Die Registrierung im sicheren nicht öffentlichen Teil der EU-Datenbank vornehmen, nur mit den in Art. 49 Abs. 4 genannten Angaben; nur die Kommission und die in Art. 74 Abs. 8 genannten Behörden haben Zugang.', 'prove', null),
  ('hr-registration-non-public', 71, 'deployer', 'high_risk', 'annex_iii', 'Register in the secure non-public section of the EU database, with only the reduced set of information Art. 49(4) lists; only the Commission and the authorities in Art. 74(8) can see it.', 'art:49:4', '2027-12-02', 'The system is listed in Annex III point 1, 6 or 7 and is used in law enforcement, migration, asylum or border control management.', false, null, 'Replaces the public registration of Art. 49(1) to (3) for these systems.', 'amended', 'Register it in the non-public section of the EU database', 'Es im nicht öffentlichen Teil der EU-Datenbank registrieren', 'Die Registrierung im sicheren nicht öffentlichen Teil der EU-Datenbank vornehmen, nur mit den in Art. 49 Abs. 4 genannten Angaben; nur die Kommission und die in Art. 74 Abs. 8 genannten Behörden haben Zugang.', 'prove', null),
  ('hr-importer-verify', 72, 'importer', 'high_risk', 'annex_i', 'Before placing the system on the market, verify that the provider carried out the conformity assessment, drew up the technical documentation, affixed the CE marking with the declaration of conformity and instructions, and appointed an authorised representative.', 'art:23:1', '2028-08-02', null, false, null, null, 'amended', 'Before you bring it to market, check the provider did its conformity work', 'Vor dem Inverkehrbringen prüfen, ob der Anbieter seine Konformitätspflichten erfüllt hat', 'Vor dem Inverkehrbringen überprüfen, ob der Anbieter das Konformitätsbewertungsverfahren durchgeführt und die technische Dokumentation erstellt hat, ob das System mit der CE- Kennzeichnung versehen ist und ihm die EU-Konformitätserklärung und die Betriebsanleitung beigefügt sind und ob der Anbieter einen Bevollmächtigten benannt hat.', null, null),
  ('hr-importer-verify', 73, 'importer', 'high_risk', 'annex_iii', 'Before placing the system on the market, verify that the provider carried out the conformity assessment, drew up the technical documentation, affixed the CE marking with the declaration of conformity and instructions, and appointed an authorised representative.', 'art:23:1', '2027-12-02', null, false, null, null, 'amended', 'Before you bring it to market, check the provider did its conformity work', 'Vor dem Inverkehrbringen prüfen, ob der Anbieter seine Konformitätspflichten erfüllt hat', 'Vor dem Inverkehrbringen überprüfen, ob der Anbieter das Konformitätsbewertungsverfahren durchgeführt und die technische Dokumentation erstellt hat, ob das System mit der CE- Kennzeichnung versehen ist und ihm die EU-Konformitätserklärung und die Betriebsanleitung beigefügt sind und ob der Anbieter einen Bevollmächtigten benannt hat.', null, null),
  ('hr-importer-nonconformity', 74, 'importer', 'high_risk', 'annex_i', 'Do not place a non-conforming or falsified system on the market; if it presents a risk, inform the provider, the authorised representative and the authorities.', 'art:23:2', '2028-08-02', null, false, null, null, 'amended', 'Don''t bring a non-conforming or falsified system to market; report risks', 'Kein nichtkonformes oder gefälschtes System in Verkehr bringen; Risiken melden', 'Ein nichtkonformes oder gefälschtes System nicht in Verkehr bringen; birgt es ein Risiko, den Anbieter, den Bevollmächtigten und die Marktüberwachungsbehörden informieren.', null, null),
  ('hr-importer-nonconformity', 75, 'importer', 'high_risk', 'annex_iii', 'Do not place a non-conforming or falsified system on the market; if it presents a risk, inform the provider, the authorised representative and the authorities.', 'art:23:2', '2027-12-02', null, false, null, null, 'amended', 'Don''t bring a non-conforming or falsified system to market; report risks', 'Kein nichtkonformes oder gefälschtes System in Verkehr bringen; Risiken melden', 'Ein nichtkonformes oder gefälschtes System nicht in Verkehr bringen; birgt es ein Risiko, den Anbieter, den Bevollmächtigten und die Marktüberwachungsbehörden informieren.', null, null),
  ('hr-importer-contact', 76, 'importer', 'high_risk', 'annex_i', 'Put your name, registered trade name or trade mark and contact address on the system and its packaging or documentation.', 'art:23:3', '2028-08-02', null, false, null, null, 'amended', 'Put your name and contact address on its packaging or documentation', 'Ihren Namen und Ihre Kontaktanschrift auf der Verpackung oder in der Dokumentation angeben', 'Ihren Namen, Ihren eingetragenen Handelsnamen oder Ihre eingetragene Handelsmarke und Ihre Kontaktanschrift auf der Verpackung oder gegebenenfalls in der beigefügten Dokumentation angeben.', null, null),
  ('hr-importer-contact', 77, 'importer', 'high_risk', 'annex_iii', 'Put your name, registered trade name or trade mark and contact address on the system and its packaging or documentation.', 'art:23:3', '2027-12-02', null, false, null, null, 'amended', 'Put your name and contact address on its packaging or documentation', 'Ihren Namen und Ihre Kontaktanschrift auf der Verpackung oder in der Dokumentation angeben', 'Ihren Namen, Ihren eingetragenen Handelsnamen oder Ihre eingetragene Handelsmarke und Ihre Kontaktanschrift auf der Verpackung oder gegebenenfalls in der beigefügten Dokumentation angeben.', null, null),
  ('hr-importer-storage', 78, 'importer', 'high_risk', 'annex_i', 'Make sure storage and transport do not jeopardise the system''s compliance while it is under your responsibility.', 'art:23:4', '2028-08-02', null, false, null, null, 'amended', 'Store and transport it so it stays compliant', 'Lagerung und Transport so gestalten, dass es konform bleibt', 'Sicherstellen, dass die Lagerungs- oder Transportbedingungen die Konformität des Systems nicht beeinträchtigen, solange es sich in Ihrer Verantwortung befindet.', null, null),
  ('hr-importer-storage', 79, 'importer', 'high_risk', 'annex_iii', 'Make sure storage and transport do not jeopardise the system''s compliance while it is under your responsibility.', 'art:23:4', '2027-12-02', null, false, null, null, 'amended', 'Store and transport it so it stays compliant', 'Lagerung und Transport so gestalten, dass es konform bleibt', 'Sicherstellen, dass die Lagerungs- oder Transportbedingungen die Konformität des Systems nicht beeinträchtigen, solange es sich in Ihrer Verantwortung befindet.', null, null),
  ('hr-importer-keep-documents', 80, 'importer', 'high_risk', 'annex_i', 'Keep the notified body''s certificate (if any), the instructions for use and the declaration of conformity for 10 years.', 'art:23:5', '2028-08-02', null, false, null, null, 'amended', 'Keep the certificate, instructions and declaration for 10 years', 'Bescheinigung, Betriebsanleitung und Konformitätserklärung zehn Jahre bereithalten', 'Ein Exemplar der Bescheinigung der notifizierten Stelle (falls vorhanden), die Betriebsanleitung und die EU-Konformitätserklärung zehn Jahre lang bereithalten.', null, null),
  ('hr-importer-keep-documents', 81, 'importer', 'high_risk', 'annex_iii', 'Keep the notified body''s certificate (if any), the instructions for use and the declaration of conformity for 10 years.', 'art:23:5', '2027-12-02', null, false, null, null, 'amended', 'Keep the certificate, instructions and declaration for 10 years', 'Bescheinigung, Betriebsanleitung und Konformitätserklärung zehn Jahre bereithalten', 'Ein Exemplar der Bescheinigung der notifizierten Stelle (falls vorhanden), die Betriebsanleitung und die EU-Konformitätserklärung zehn Jahre lang bereithalten.', null, null),
  ('hr-importer-provide-information', 82, 'importer', 'high_risk', 'annex_i', 'Give the competent authorities the information and documentation they ask for to demonstrate conformity.', 'art:23:6', '2028-08-02', null, false, null, null, 'amended', 'Give the authorities the documents they ask for', 'Den Behörden auf Anfrage die nötigen Unterlagen übermitteln', 'Den zuständigen Behörden auf begründete Anfrage alle Informationen und Dokumentation übermitteln, die zum Nachweis der Konformität des Systems erforderlich sind.', null, null),
  ('hr-importer-provide-information', 83, 'importer', 'high_risk', 'annex_iii', 'Give the competent authorities the information and documentation they ask for to demonstrate conformity.', 'art:23:6', '2027-12-02', null, false, null, null, 'amended', 'Give the authorities the documents they ask for', 'Den Behörden auf Anfrage die nötigen Unterlagen übermitteln', 'Den zuständigen Behörden auf begründete Anfrage alle Informationen und Dokumentation übermitteln, die zum Nachweis der Konformität des Systems erforderlich sind.', null, null),
  ('hr-importer-cooperate', 84, 'importer', 'high_risk', 'annex_i', 'Cooperate with the competent authorities in any action they take about the system.', 'art:23:7', '2028-08-02', null, false, null, null, 'amended', 'Cooperate with the authorities when they act on it', 'Mit den Behörden bei ihren Maßnahmen zusammenarbeiten', 'Mit den zuständigen Behörden bei allen Maßnahmen zusammenarbeiten, die diese im Zusammenhang mit dem System ergreifen.', null, null),
  ('hr-importer-cooperate', 85, 'importer', 'high_risk', 'annex_iii', 'Cooperate with the competent authorities in any action they take about the system.', 'art:23:7', '2027-12-02', null, false, null, null, 'amended', 'Cooperate with the authorities when they act on it', 'Mit den Behörden bei ihren Maßnahmen zusammenarbeiten', 'Mit den zuständigen Behörden bei allen Maßnahmen zusammenarbeiten, die diese im Zusammenhang mit dem System ergreifen.', null, null),
  ('hr-distributor-verify', 86, 'distributor', 'high_risk', 'annex_i', 'Before making the system available, verify the CE marking, the declaration of conformity and instructions for use, and that the provider and importer put their names and contact details on it.', 'art:24:1', '2028-08-02', null, false, null, null, 'amended', 'Before you supply it, check its CE marking, declaration and instructions', 'Vor der Bereitstellung CE-Kennzeichnung, Erklärung und Betriebsanleitung prüfen', 'Vor der Bereitstellung auf dem Markt überprüfen, ob das System mit der CE-Kennzeichnung versehen ist, ob ihm die EU-Konformitätserklärung und die Betriebsanleitung beigefügt sind und ob Anbieter und Einführer ihren Namen und ihre Kontaktanschrift angegeben haben.', null, null),
  ('hr-distributor-verify', 87, 'distributor', 'high_risk', 'annex_iii', 'Before making the system available, verify the CE marking, the declaration of conformity and instructions for use, and that the provider and importer put their names and contact details on it.', 'art:24:1', '2027-12-02', null, false, null, null, 'amended', 'Before you supply it, check its CE marking, declaration and instructions', 'Vor der Bereitstellung CE-Kennzeichnung, Erklärung und Betriebsanleitung prüfen', 'Vor der Bereitstellung auf dem Markt überprüfen, ob das System mit der CE-Kennzeichnung versehen ist, ob ihm die EU-Konformitätserklärung und die Betriebsanleitung beigefügt sind und ob Anbieter und Einführer ihren Namen und ihre Kontaktanschrift angegeben haben.', null, null),
  ('hr-distributor-nonconformity', 88, 'distributor', 'high_risk', 'annex_i', 'Do not make a non-conforming system available; if it presents a risk, inform the provider or importer.', 'art:24:2', '2028-08-02', null, false, null, null, 'amended', 'Don''t supply a non-conforming system; report risks to the provider or importer', 'Kein nichtkonformes System bereitstellen; Risiken dem Anbieter oder Einführer melden', 'Ein nichtkonformes System nicht auf dem Markt bereitstellen; birgt es ein Risiko, den Anbieter oder den Einführer informieren.', null, null),
  ('hr-distributor-nonconformity', 89, 'distributor', 'high_risk', 'annex_iii', 'Do not make a non-conforming system available; if it presents a risk, inform the provider or importer.', 'art:24:2', '2027-12-02', null, false, null, null, 'amended', 'Don''t supply a non-conforming system; report risks to the provider or importer', 'Kein nichtkonformes System bereitstellen; Risiken dem Anbieter oder Einführer melden', 'Ein nichtkonformes System nicht auf dem Markt bereitstellen; birgt es ein Risiko, den Anbieter oder den Einführer informieren.', null, null),
  ('hr-distributor-storage', 90, 'distributor', 'high_risk', 'annex_i', 'Make sure storage and transport do not jeopardise the system''s compliance while it is under your responsibility.', 'art:24:3', '2028-08-02', null, false, null, null, 'amended', 'Store and transport it so it stays compliant', 'Lagerung und Transport so gestalten, dass es konform bleibt', 'Sicherstellen, dass die Lagerungs- oder Transportbedingungen die Konformität des Systems nicht beeinträchtigen, solange es sich in Ihrer Verantwortung befindet.', null, null),
  ('hr-distributor-storage', 91, 'distributor', 'high_risk', 'annex_iii', 'Make sure storage and transport do not jeopardise the system''s compliance while it is under your responsibility.', 'art:24:3', '2027-12-02', null, false, null, null, 'amended', 'Store and transport it so it stays compliant', 'Lagerung und Transport so gestalten, dass es konform bleibt', 'Sicherstellen, dass die Lagerungs- oder Transportbedingungen die Konformität des Systems nicht beeinträchtigen, solange es sich in Ihrer Verantwortung befindet.', null, null),
  ('hr-distributor-corrective-actions', 92, 'distributor', 'high_risk', 'annex_i', 'For a non-conforming system you made available, take corrective action, withdraw or recall it, or make sure the provider or importer does.', 'art:24:4', '2028-08-02', null, false, null, null, 'amended', 'Fix, withdraw or recall a non-conforming system you supplied', 'Ein nichtkonformes System korrigieren, zurücknehmen oder zurückrufen', 'Für ein nichtkonformes System, das Sie auf dem Markt bereitgestellt haben, die erforderlichen Korrekturmaßnahmen ergreifen, es zurücknehmen oder zurückrufen oder sicherstellen, dass der Anbieter oder der Einführer dies tut.', null, null),
  ('hr-distributor-corrective-actions', 93, 'distributor', 'high_risk', 'annex_iii', 'For a non-conforming system you made available, take corrective action, withdraw or recall it, or make sure the provider or importer does.', 'art:24:4', '2027-12-02', null, false, null, null, 'amended', 'Fix, withdraw or recall a non-conforming system you supplied', 'Ein nichtkonformes System korrigieren, zurücknehmen oder zurückrufen', 'Für ein nichtkonformes System, das Sie auf dem Markt bereitgestellt haben, die erforderlichen Korrekturmaßnahmen ergreifen, es zurücknehmen oder zurückrufen oder sicherstellen, dass der Anbieter oder der Einführer dies tut.', null, null),
  ('hr-distributor-provide-information', 94, 'distributor', 'high_risk', 'annex_i', 'Give the competent authorities the information and documentation they ask for about your actions.', 'art:24:5', '2028-08-02', null, false, null, null, 'amended', 'Give the authorities information about what you did', 'Den Behörden auf Anfrage Auskunft über Ihre Maßnahmen geben', 'Den zuständigen Behörden auf begründete Anfrage alle Informationen und Dokumentation zu Ihren Maßnahmen übermitteln.', null, null),
  ('hr-distributor-provide-information', 95, 'distributor', 'high_risk', 'annex_iii', 'Give the competent authorities the information and documentation they ask for about your actions.', 'art:24:5', '2027-12-02', null, false, null, null, 'amended', 'Give the authorities information about what you did', 'Den Behörden auf Anfrage Auskunft über Ihre Maßnahmen geben', 'Den zuständigen Behörden auf begründete Anfrage alle Informationen und Dokumentation zu Ihren Maßnahmen übermitteln.', null, null),
  ('hr-distributor-cooperate', 96, 'distributor', 'high_risk', 'annex_i', 'Cooperate with the competent authorities in any action they take about the system.', 'art:24:6', '2028-08-02', null, false, null, null, 'amended', 'Cooperate with the authorities when they act on it', 'Mit den Behörden bei ihren Maßnahmen zusammenarbeiten', 'Mit den zuständigen Behörden bei allen Maßnahmen zusammenarbeiten, die diese im Zusammenhang mit dem System ergreifen.', null, null),
  ('hr-distributor-cooperate', 97, 'distributor', 'high_risk', 'annex_iii', 'Cooperate with the competent authorities in any action they take about the system.', 'art:24:6', '2027-12-02', null, false, null, null, 'amended', 'Cooperate with the authorities when they act on it', 'Mit den Behörden bei ihren Maßnahmen zusammenarbeiten', 'Mit den zuständigen Behörden bei allen Maßnahmen zusammenarbeiten, die diese im Zusammenhang mit dem System ergreifen.', null, null),
  ('transparency-interaction', 98, 'provider', 'limited_risk', null, 'Design the system so that people are informed they are interacting with an AI system, unless that is obvious.', 'art:50:1', '2026-08-02', 'The system is intended to interact directly with natural persons.', false, null, null, 'amended', 'Tell people they''re talking to an AI system', 'Personen darüber informieren, dass sie mit einem KI-System interagieren', 'Das System so konzipieren und entwickeln, dass Personen informiert werden, dass sie mit einem KI-System interagieren, es sei denn, dies ist offensichtlich.', 'build', null),
  ('transparency-interaction', 99, 'provider', 'high_risk', null, 'Design the system so that people are informed they are interacting with an AI system, unless that is obvious.', 'art:50:1', '2026-08-02', 'The system is intended to interact directly with natural persons.', false, null, null, 'amended', 'Tell people they''re talking to an AI system', 'Personen darüber informieren, dass sie mit einem KI-System interagieren', 'Das System so konzipieren und entwickeln, dass Personen informiert werden, dass sie mit einem KI-System interagieren, es sei denn, dies ist offensichtlich.', 'build', null),
  ('transparency-marking', 100, 'provider', 'limited_risk', null, 'Mark the system''s outputs in a machine-readable format so they are detectable as artificially generated or manipulated.', 'art:50:2', '2026-08-02', 'The system generates synthetic audio, image, video or text content.', false, null, 'Systems placed on the market before 2 August 2026 have until 2 December 2026 to comply (Art. 111(4), added by the Omnibus).', 'amended', 'Mark its outputs as AI-generated in a machine-readable way', 'Die Ausgaben maschinenlesbar als KI-erzeugt kennzeichnen', 'Die Ausgaben des Systems in einem maschinenlesbaren Format kennzeichnen, sodass sie als künstlich erzeugt oder manipuliert erkennbar sind.', 'build', null),
  ('transparency-marking', 101, 'provider', 'high_risk', null, 'Mark the system''s outputs in a machine-readable format so they are detectable as artificially generated or manipulated.', 'art:50:2', '2026-08-02', 'The system generates synthetic audio, image, video or text content.', false, null, 'Systems placed on the market before 2 August 2026 have until 2 December 2026 to comply (Art. 111(4), added by the Omnibus).', 'amended', 'Mark its outputs as AI-generated in a machine-readable way', 'Die Ausgaben maschinenlesbar als KI-erzeugt kennzeichnen', 'Die Ausgaben des Systems in einem maschinenlesbaren Format kennzeichnen, sodass sie als künstlich erzeugt oder manipuliert erkennbar sind.', 'build', null),
  ('transparency-emotion-biometric', 102, 'deployer', 'limited_risk', null, 'Inform the people exposed to the system that it is operating, and process their personal data under the GDPR.', 'art:50:3', '2026-08-02', 'The system is an emotion recognition or biometric categorisation system.', false, null, null, 'amended', 'Tell people the emotion recognition or biometric categorisation is running', 'Betroffene informieren, dass Emotionserkennung oder biometrische Kategorisierung läuft', 'Die betroffenen natürlichen Personen über den Betrieb des Systems informieren und personenbezogene Daten gemäß der Verordnung (EU) 2016/679 (DSGVO) verarbeiten.', null, 'art_50_3_disclosure'),
  ('transparency-emotion-biometric', 103, 'deployer', 'high_risk', null, 'Inform the people exposed to the system that it is operating, and process their personal data under the GDPR.', 'art:50:3', '2026-08-02', 'The system is an emotion recognition or biometric categorisation system.', false, null, null, 'amended', 'Tell people the emotion recognition or biometric categorisation is running', 'Betroffene informieren, dass Emotionserkennung oder biometrische Kategorisierung läuft', 'Die betroffenen natürlichen Personen über den Betrieb des Systems informieren und personenbezogene Daten gemäß der Verordnung (EU) 2016/679 (DSGVO) verarbeiten.', null, 'art_50_3_disclosure'),
  ('transparency-deep-fake', 104, 'deployer', 'limited_risk', null, 'Disclose that deep-fake image, audio or video content, or text published to inform the public on matters of public interest, has been artificially generated or manipulated.', 'art:50:4', '2026-08-02', 'The system generates or manipulates deep fakes, or text published to inform the public on matters of public interest (not needed for text under human editorial control).', false, null, null, 'amended', 'Disclose AI-made content that could pass as real', 'Offenlegen, wenn Inhalte echt wirken, aber KI-erzeugt sind', 'Offenlegen, dass Deepfake-Bild-, Ton- oder Videoinhalte oder Texte, die veröffentlicht werden, um die Öffentlichkeit über Angelegenheiten von öffentlichem Interesse zu informieren, künstlich erzeugt oder manipuliert wurden.', null, 'art_50_4_disclosure'),
  ('transparency-deep-fake', 105, 'deployer', 'high_risk', null, 'Disclose that deep-fake image, audio or video content, or text published to inform the public on matters of public interest, has been artificially generated or manipulated.', 'art:50:4', '2026-08-02', 'The system generates or manipulates deep fakes, or text published to inform the public on matters of public interest (not needed for text under human editorial control).', false, null, null, 'amended', 'Disclose AI-made content that could pass as real', 'Offenlegen, wenn Inhalte echt wirken, aber KI-erzeugt sind', 'Offenlegen, dass Deepfake-Bild-, Ton- oder Videoinhalte oder Texte, die veröffentlicht werden, um die Öffentlichkeit über Angelegenheiten von öffentlichem Interesse zu informieren, künstlich erzeugt oder manipuliert wurden.', null, 'art_50_4_disclosure'),
  ('annex-iii-exemption', 106, 'provider', 'limited_risk', null, 'Document the assessment before placing the system on the market, register it in the EU database (Art. 49(2)), and hand the assessment to national authorities on request.', 'art:6:4', '2027-12-02', 'The system is listed in Annex III, but you concluded under Art. 6(3) that it is not high-risk.', false, null, 'The Omnibus kept this registration but simplified its content (Omnibus recital 22). The date follows Art. 113(c)(i), but that covers systems "classified as high-risk"; a literal reading (and Art. 49 being in Chapter VIII) gives 2 August 2026. Check with a lawyer.', 'amended', 'Document why it isn''t high-risk, and register it', 'Dokumentieren, warum es nicht hochriskant ist, und es registrieren', 'Die Bewertung vor dem Inverkehrbringen oder der Inbetriebnahme dokumentieren, das System in der EU-Datenbank registrieren (Art. 49 Abs. 2) und die Dokumentation der Bewertung den zuständigen nationalen Behörden auf Verlangen vorlegen.', 'prove', null),
  ('annex-iii-exemption', 107, 'provider', 'minimal_risk', null, 'Document the assessment before placing the system on the market, register it in the EU database (Art. 49(2)), and hand the assessment to national authorities on request.', 'art:6:4', '2027-12-02', 'The system is listed in Annex III, but you concluded under Art. 6(3) that it is not high-risk.', false, null, 'The Omnibus kept this registration but simplified its content (Omnibus recital 22). The date follows Art. 113(c)(i), but that covers systems "classified as high-risk"; a literal reading (and Art. 49 being in Chapter VIII) gives 2 August 2026. Check with a lawyer.', 'amended', 'Document why it isn''t high-risk, and register it', 'Dokumentieren, warum es nicht hochriskant ist, und es registrieren', 'Die Bewertung vor dem Inverkehrbringen oder der Inbetriebnahme dokumentieren, das System in der EU-Datenbank registrieren (Art. 49 Abs. 2) und die Dokumentation der Bewertung den zuständigen nationalen Behörden auf Verlangen vorlegen.', 'prove', null),
  ('gpai-model-provider-duties', 108, 'provider', 'high_risk', null, 'The provider of the general-purpose AI model has its own duties under Chapter V (Art. 53, and Art. 55 for models with systemic risk), which this assessment doesn''t cover. It must give you the information and documentation you need to understand the model''s capabilities and limitations and to meet your own duties (Art. 53(1)(b)).', 'art:53:1:b', '2025-08-02', 'The system is built on a general-purpose AI model from another provider.', true, null, 'Chapter V applies from 2 August 2025 (Art. 113(b)).', 'amended', 'Get the information you need from the model''s maker', 'Vom Anbieter des Modells die Informationen erhalten, die Sie brauchen', 'Der Anbieter des KI-Modells mit allgemeinem Verwendungszweck hat eigene Pflichten nach Kapitel V (Art. 53, bei Modellen mit systemischem Risiko auch Art. 55), die diese Bewertung nicht abdeckt. Er muss Ihnen die Informationen und die Dokumentation bereitstellen, die Sie brauchen, um die Fähigkeiten und Grenzen des Modells zu verstehen und Ihren eigenen Pflichten nachzukommen (Art. 53 Abs. 1 Buchst. b).', 'build', null),
  ('gpai-model-provider-duties', 109, 'provider', 'limited_risk', null, 'The provider of the general-purpose AI model has its own duties under Chapter V (Art. 53, and Art. 55 for models with systemic risk), which this assessment doesn''t cover. It must give you the information and documentation you need to understand the model''s capabilities and limitations and to meet your own duties (Art. 53(1)(b)).', 'art:53:1:b', '2025-08-02', 'The system is built on a general-purpose AI model from another provider.', true, null, 'Chapter V applies from 2 August 2025 (Art. 113(b)).', 'amended', 'Get the information you need from the model''s maker', 'Vom Anbieter des Modells die Informationen erhalten, die Sie brauchen', 'Der Anbieter des KI-Modells mit allgemeinem Verwendungszweck hat eigene Pflichten nach Kapitel V (Art. 53, bei Modellen mit systemischem Risiko auch Art. 55), die diese Bewertung nicht abdeckt. Er muss Ihnen die Informationen und die Dokumentation bereitstellen, die Sie brauchen, um die Fähigkeiten und Grenzen des Modells zu verstehen und Ihren eigenen Pflichten nachzukommen (Art. 53 Abs. 1 Buchst. b).', 'build', null),
  ('gpai-model-provider-duties', 110, 'provider', 'minimal_risk', null, 'The provider of the general-purpose AI model has its own duties under Chapter V (Art. 53, and Art. 55 for models with systemic risk), which this assessment doesn''t cover. It must give you the information and documentation you need to understand the model''s capabilities and limitations and to meet your own duties (Art. 53(1)(b)).', 'art:53:1:b', '2025-08-02', 'The system is built on a general-purpose AI model from another provider.', true, null, 'Chapter V applies from 2 August 2025 (Art. 113(b)).', 'amended', 'Get the information you need from the model''s maker', 'Vom Anbieter des Modells die Informationen erhalten, die Sie brauchen', 'Der Anbieter des KI-Modells mit allgemeinem Verwendungszweck hat eigene Pflichten nach Kapitel V (Art. 53, bei Modellen mit systemischem Risiko auch Art. 55), die diese Bewertung nicht abdeckt. Er muss Ihnen die Informationen und die Dokumentation bereitstellen, die Sie brauchen, um die Fähigkeiten und Grenzen des Modells zu verstehen und Ihren eigenen Pflichten nachzukommen (Art. 53 Abs. 1 Buchst. b).', 'build', null);
